async function updateTree(t){setTrees(v=>v.map(x=>x.id===t.id?t:x));if(configured&&user){setSaving(true);try{await saveTree(t,user.id)}catch(e){flash('Не сохранено: '+e.message,true)}finally{setSaving(false)}}}
function openTree(t){setActiveId(t.id);setChosen(null);setOffset({x:0,y:0});setScale(.9);setView('editor');setModal(null);setMobileNav(false)}
async function createTree(title){if(!trim(title))throw Error('Введите название династии');if(configured&&!user)throw Error('Для сохранения войдите в аккаунт');const t={id:uid(),owner_id:user?.id||null,title:trim(title),description:'',cover:'',public:false,people:[],created_at:new Date().toISOString()};if(db)await saveTree(t,user.id);setTrees(a=>[t,...a]);openTree(t);setEditing(null);setModal('createSim')}
async function deleteTree(){if(!active)return;if(db){try{await removeTree(active.id)}catch(e){return flash(e.message,true)}}const next=trees.filter(t=>t.id!==activeId);setTrees(next);setActiveId(next[0]?.id||null);setView('dashboard');setModal(null);flash('Династия удалена')}
function replacePeople(next,persist=true){if(!active)return;const tree={...active,people:next};setTrees(v=>v.map(t=>t.id===active.id?tree:t));if(persist&&configured&&user){setSaving(true);saveTree(tree,user.id).catch(e=>flash('Не сохранено: '+e.message,true)).finally(()=>setSaving(false));}}
function mutatePeople(next){replacePeople(next,true)}
function movePersonLive(id,x,y){if(!active)return;replacePeople((active.people||[]).map(p=>p.id===id?{...p,x,y}:p),false)}
function persistPersonPosition(id,x,y){if(!active)return;mutatePeople((active.people||[]).map(p=>p.id===id?{...p,x,y}:p))}
async function imageFile(file){if(!file)return null;if(!file.type.startsWith('image/'))throw Error('Пожалуйста, выберите фотографию');if(file.size>8e6)throw Error('Максимальный размер фотографии — 8 МБ');if(db&&user)return await uploadPhoto(file,user.id);return await new Promise((resolve,reject)=>{const im=new Image();const url=URL.createObjectURL(file);im.onload=()=>{const cvs=document.createElement('canvas');const s=Math.min(1,1100/Math.max(im.width,im.height));cvs.width=Math.round(im.width*s);cvs.height=Math.round(im.height*s);cvs.getContext('2d').drawImage(im,0,0,cvs.width,cvs.height);URL.revokeObjectURL(url);resolve(cvs.toDataURL('image/jpeg',.77))};im.onerror=()=>reject(Error('Не удалось прочитать фотографию'));im.src=url})}
async function savePerson(d){
  if(!trim(d.name))throw Error('Введите имя персонажа');
  const previous=editing?people.find(x=>x.id===editing.id):null;
  // Crucial: preserve relations, parents, partner and any future fields when editing.
  const p={...(previous||{}),...d,name:trim(d.name),gen:Number(d.gen)||1};
  if(previous){if(!Number.isFinite(Number(p.x)))p.x=previous.x??100;if(!Number.isFinite(Number(p.y)))p.y=previous.y??100;mutatePeople(people.map(x=>x.id===previous.id?p:x));}
  else {p.id=uid();p.parents=[];p.partner='';p.relations=[];
    if(!Number.isFinite(Number(p.x)))p.x=100+people.filter(x=>x.gen===p.gen).length*260;
    if(!Number.isFinite(Number(p.y)))p.y=80+(p.gen-1)*290;
    mutatePeople([...people,p]);}
  setChosen(p.id);setModal(null);setEditing(null);flash('Карточка персонажа сохранена');
}

function deletePerson(){if(!selected)return;mutatePeople(people.filter(p=>p.id!==selected.id).map(p=>({...p,parents:(p.parents||[]).filter(id=>id!==selected.id),partner:p.partner===selected.id?'':p.partner,relations:(p.relations||[]).filter(r=>r.to!==selected.id)})));setChosen(null);setModal(null)}
function addRelationship(other,type,options={}){try{mutatePeople(setRelation(people,chosen,other,type,options));if(modal==='relation')setModal(null);flash('Связь сохранена')}catch(e){flash(e.message,true);throw e}}
function deleteRelationship(other,type){mutatePeople(removeRelation(people,chosen,other,type));flash('Связь удалена')}
