function AuthForm({tab,setTab,onClose,onSuccess,flash}){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[name,setName]=useState(''),[busy,setBusy]=useState(false),[msg,setMsg]=useState('');async function submit(e){e.preventDefault();if(!configured){setMsg('Для настоящей регистрации администратору нужно подключить Supabase.');return}setBusy(true);try{if(tab==='register'){const{data,error}=await db.auth.signUp({email,password,options:{data:{display_name:name}}});if(error)throw error;if(data.session)onSuccess();else setMsg('Проверьте почту и подтвердите регистрацию, затем войдите.')}else{const{error}=await db.auth.signInWithPassword({email,password});if(error)throw error;onSuccess()}}catch(e){setMsg(e.message)}finally{setBusy(false)}}return <><div className="modal-eyebrow">ДОБРО ПОЖАЛОВАТЬ</div><h2>{tab==='register'?'Начните свою историю':'С возвращением!'}</h2><p className="modal-desc">{tab==='register'?'Создайте аккаунт, чтобы сохранять и публиковать династии.':'Продолжите историю своей семьи.'}</p><div className="auth-tabs"><button className={tab==='register'?'sel':''} onClick={()=>{setTab('register');setMsg('')}}>Регистрация</button><button className={tab==='login'?'sel':''} onClick={()=>{setTab('login');setMsg('')}}>Вход</button></div><form className="form" onSubmit={submit}>{tab==='register'&&<label>Имя пользователя<input required value={name} onChange={e=>setName(e.target.value)} placeholder="Ваш никнейм"/></label>}<label>Email<input required type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/></label><label>Пароль<input required type="password" minLength={6} value={password} onChange={e=>setPassword(e.target.value)} placeholder="Не менее 6 символов"/></label>{msg&&<p className="form-message">{msg}</p>}<button className="btn btn-green btn-full" disabled={busy}>{busy?'Подождите...':tab==='register'?'Зарегистрироваться':'Войти'} <ArrowRight size={16}/></button></form>{!configured&&<p className="modal-note">Сейчас сайт в демонстрационном режиме. Можно создавать древа без аккаунта, но они сохраняются только в этом браузере.</p>}</>}
function NewTreeForm({onSubmit,onCancel}){const [title,setTitle]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState('');return <><div className="modal-eyebrow">НОВАЯ ИСТОРИЯ</div><h2>Создать династию</h2><p className="modal-desc">Как называется семья, чью историю вы хотите сохранить?</p><form className="form" onSubmit={async e=>{e.preventDefault();setBusy(true);try{await onSubmit(title)}catch(e){setError(e.message)}finally{setBusy(false)}}}><label>Название династии<input autoFocus required maxLength={80} value={title} onChange={e=>setTitle(e.target.value)} placeholder="Например, Семья Блум"/></label>{error&&<p className="form-message">{error}</p>}<button className="btn btn-green btn-full" disabled={busy}>Создать древо <ArrowRight size={16}/></button></form></>}
